"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[6122],{96122:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/the-courage-to-be-hated.png\\"\\n          title=\\"미움받을 용기\\"\\n          author=\\"기시미 이치로\\"\\n          publisher=\\"인플루엔셜\\"\\n          publishedDate=\\"2014-11-17\\"\\n          isbn=\\"9788996991342\\"\\n          rating=3.5\\n          tags=\\"humanities\\"\\n        />\\n</center>\\n\\n## Review\\n<mark>알프레드 아들러</mark>의 사상을 ```철학자와 청년의 대화```라는 형식으로 쉽고 명쾌하게 풀어낸 책이다.  \\n과거의 <mark>트라우마</mark>가 현재를 결정한다는 프로이트의 ```원인론```을 정면으로 반박하며, 모든 것은 현재의 <mark>목적</mark>을 위해 스스로 선택한 것이라는 ```목적론```적 관점을 제시한다.  \\n<br>\\n트라우마에 대해서 너무 가볍게 생각하는 거 아닌가 하는 반발이 조금 들게 만드는 책이었다.  \\n우리가 변하지 못하는 이유는 변할 수 없어서가 아니라, 변하지 않겠다고 스스로 ```결심```했기 때문이라는 충격적인 주장은 극복할 수 있지만 너는 단지 노력하지 않았다는 폭력적인 주장 같다.  \\n<br>\\n모든 고민은 인간관계에서 비롯된다는 것은 공감되고 이는 우리의 생존을 위해 어쩔 수 없을 것이다.  \\n모든 생물은 생존을 위해서 사회에 속하는 것이 유리하며 이러한 사회에서 도태되는 것은 곧 생존의 위협이기 때문에 스트레스를 받는 것이 정상일 것이다.  \\n<br>\\n너의 노력이 부족하다 너무 채찍질하는 책인 것 같지만 그래도 ```아들러``` 심리학에 관심을 가질 수 있게 해줬던 책이다."}')}}]);